HEADER = [
    "lit_id", "子库", "文件名", "类型", "公开号_出处", "机构", "年份", "作者_申请人",
    "处理链路", "证据层级", "sha256_12", "相关度", "威胁评估", "五步链覆盖要点",
    "一句话要点", "待核实", "备注",
]

# 证据层级映射（2026-09-07 口径修订）：扉页级行的"无覆盖"仅表示扉页摘要未披露
# 该机制，不得解读为对应专利全文不存在该机制（01 号报告 §3 口径）。
EVIDENCE_LEVEL = {
    "converted_fulltext": "全文级",
    "duplicate_sha256": "全文级(重复件)",
    "ocr_frontpage": "扉页级",
    "ocr_fulltext": "全文级(OCR)",
    "failed_unreadable": "损坏",
}


def main() -> None:
    hashes = {}
    for r in csv.DictReader(LOG.open(encoding="utf-8-sig")):
        hashes[r["rel_path"]] = r["sha256"][:12]

    rows = []
    for rec in D:
        (
            lit_id, sub, fname, dtype, pub, org, year, resp, proc,
            rel, threat, chain, summ, follow, note,
        ) = rec
        rel_path = f"{sub}\\{fname}" if sub != "顶层" else fname
        sha = hashes.get(rel_path, "")
        rows.append(
            {
                "lit_id": lit_id, "子库": sub, "文件名": fname, "类型": dtype,
                "公开号_出处": pub, "机构": org, "年份": year, "作者_申请人": resp,
                "处理链路": proc, "证据层级": EVIDENCE_LEVEL.get(proc, ""),
                "sha256_12": sha, "相关度": rel, "威胁评估": threat,
                "五步链覆盖要点": chain, "一句话要点": summ, "待核实": follow, "备注": note,
            }
        )

    with OUT.open("w", newline="", encoding="utf-8-sig") as f:
        w = csv.DictWriter(f, fieldnames=HEADER)
        w.writeheader()
        w.writerows(rows)
    print(f"written {OUT} rows={len(rows)}")
    from collections import Counter

    print("相关度:", dict(Counter(r["相关度"] for r in rows)))
    print("威胁:", dict(Counter(r["威胁评估"] for r in rows)))
    missing = [r["文件名"] for r in rows if not r["sha256_12"]]
    if missing:
        print("MISSING HASH:", missing)
    else:
        print("hash join: all 108 matched")


if __name__ == "__main__":
    main()
